import{z as A,x as i,o as l,c as p,q as s,j as o,D as e,d as r,s as n,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"任务并行","description":"","frontmatter":{"title":"任务并行","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-task-parallel.md","filePath":"cs/par-task-parallel.md","lastUpdated":1791413859000}'),d={name:"cs/par-task-parallel.md"};function f(m,a,c,h,T,u){const t=i("Mermaid");return l(),p("div",null,[a[2]||(a[2]=s('<h1 id="任务并行" tabindex="-1">任务并行 <a class="header-anchor" href="#任务并行" aria-label="Permalink to &quot;任务并行&quot;">​</a></h1><div class="epigraph"><p>并行度不必预先量好装进循环：任务把它留给运行时，让闲着的核自己去偷。</p><footer>—— 据 Blumofe and Leiserson, Journal of the ACM, 1999；Frigo, Leiserson, and Randall, The Implementation of Cilk-5, PLDI 1998 整理</footer></div><p><a href="/cs/par-data-parallel-patterns">上一课</a>把独立性写进形状，代价是并行度必须在写代码时就知道：map 多少元素、scan 多长，静态可数。树遍历、图搜索、自适应细分——它们的并行度要到运行时才现身。任务并行把「一段可跑的子计算」当单位，动态抛给运行时；<a href="/cs/work-span-model">Work-span 与 fork-join</a>已把 \\(W\\)、\\(S\\) 与 Brent 界立好，本课补工程侧：任务怎么切、调度怎么偷、粒度怎么定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务并行的中心问题是粒度与依赖的平衡。切太粗：核闲着，\\(W/P\\) 项吃亏——不平衡；切太细：派生与入队的固定开销吃掉收益，任务数失控。错法一：递归分治「两路都 spawn 到底」——任务数随深度指数增长，队列把内存吃穿；正解是 cutoff：子问题小于阈值就地串行。错法二：以为任务多就快——并行度被跨度封顶，\\(T_P\\ge S\\) 是硬下界，一百万个串行依赖的任务不会比一条链快。错法三：在任务里随手共享可变状态——fork-join 的近最优性假设任务间无竞争，锁一进来，进度、回滚、优先级反转的问题全部回来，那是下一课的主题。</p><p><span class="marginnote">直觉类比：把一车砖搬下卡车，一块一块搬，来回跑断腿；整托盘一次抱，又抱不动。一人搬半托盘正好——cutoff 定的就是这个「半托盘」：叶子小到有得分配，大到不为搬运本身白费力气。</span></p><p><span class="marginnote">「任务多≠快」的数字版：一条 1000 步的串行依赖链，就算切成 1000 个任务、给 1000 个核，第 \\(i\\) 步仍要等第 \\(i-1\\) 步，照样跑满 1000 步——这就是 \\(T_P\\ge S\\) 的硬下界。加核加的是「能并排干的部分」，不是依赖链。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是 fork-join 加工作窃取：spawn 两半、sync 汇合；每个核一个双端队列，自己的任务底端压弹，闲核从他人顶端偷——两端分开，竞争与偷取都稀有。工程三件套：cutoff 定粒度，叶子任务给到几十微秒量级的连续工作量；窃取目标随机化，摊平不平衡；动态负载（分枝定界、不规则树）交给运行时，静态规则的循环留给上一课的数据并行。两者还常组合：外层任务并行切出大块，内层每个任务再用数据并行与 SIMD 吃满本地核。流水线也是任务并行：各阶段各挂一个队列，阶段间天然并行——<a href="/cs/pipeline-five-stage">五级流水线</a>是它在硬件里的原型，<a href="/llm/pipeline-parallel">流水线并行</a>把同一思想搬进模型切分。</p>',9)),(l(),o(B,null,{default:e(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%20T%22%5D%20--%3E%20TL%5B%22spawn%20%E5%B7%A6%E5%8D%8A%22%5D%0A%20%20T%20--%3E%20TR%5B%22spawn%20%E5%8F%B3%E5%8D%8A%22%5D%0A%20%20TL%20--%3E%20Q1%5B%22%E6%A0%B8%201%20%E5%8F%8C%E7%AB%AF%E9%98%9F%E5%88%97%E5%BA%95%E7%AB%AF%22%5D%0A%20%20TR%20--%3E%20Q2%5B%22%E6%A0%B8%202%20%E5%8F%8C%E7%AB%AF%E9%98%9F%E5%88%97%E5%BA%95%E7%AB%AF%22%5D%0A%20%20IDLE%5B%22%E9%97%B2%E6%A0%B8%22%5D%20--%3E%7C%22%E4%BB%8E%E9%A1%B6%E7%AB%AF%E5%81%B7%22%7C%20Q2%0A%20%20TL%20--%3E%20SY%5B%22sync%20%E6%B1%87%E5%90%88%22%5D%0A%20%20TR%20--%3E%20SY%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"窃取为什么近最优：偷只发生在有核闲着的时候。Blumofe–Leiserson 给出期望时间 \\(\\le W/P+O(S)\\)、空间 \\(O(P\\cdot S_1)\\)（\\(S_1\\) 是单核执行的空间）——窃取调度的最坏内存也只是单核的 \\(P\\) 倍。队列两端分工的机制：自己一端 LIFO 保热数据与递归局部性，被偷的一端 FIFO 拿走最老最大的任务，偷一次转移一大块工作。throttling 的机制：任务对象携带闭包与捕获上下文，派生速度长期超过消费速度时内存线性堆积——运行时要给未完成任务的存量设上限，否则「并行」先以内存耗尽的形式失败。",-1)),a[5]||(a[5]=E("p",null,"方法一节的图画的是「任务怎么分、怎么偷」；throttling 要防的那条失败路径——任务生得比消得快——单独画出来。",-1)),(l(),o(B,null,{default:e(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22spawn%20%E6%B4%BE%E7%94%9F%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20Q%5B%22%E6%9C%AA%E5%AE%8C%E6%88%90%E4%BB%BB%E5%8A%A1%E5%9C%A8%E9%98%9F%E5%88%97%E9%87%8C%E5%A0%86%E7%A7%AF%22%5D%0A%20%20Q%20--%3E%20RATE%7B%22%E6%B4%BE%E7%94%9F%E9%80%9F%E5%BA%A6%E9%95%BF%E6%9C%9F%E5%A4%A7%E4%BA%8E%E6%B6%88%E8%B4%B9%E9%80%9F%E5%BA%A6%3F%22%7D%0A%20%20RATE%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E5%B9%B3%E7%A8%B3%E6%B6%88%E5%8C%96%22%5D%0A%20%20RATE%20--%3E%7C%22%E6%98%AF%22%7C%20MEM%5B%22%E9%97%AD%E5%8C%85%E4%B8%8E%E6%8D%95%E8%8E%B7%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BA%BF%E6%80%A7%E5%A0%86%E7%A7%AF%22%5D%0A%20%20MEM%20--%3E%20OOM%5B%22%E5%B9%B6%E8%A1%8C%E5%85%88%E4%BB%A5%E5%86%85%E5%AD%98%E8%80%97%E5%B0%BD%E7%9A%84%E5%BD%A2%E5%BC%8F%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20OOM%20--%3E%20TH%5B%22throttling%3A%20%E7%BB%99%E6%9C%AA%E5%AE%8C%E6%88%90%E5%AD%98%E9%87%8F%E8%AE%BE%E4%B8%8A%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">cutoff 阈值不是越小越好：叶子任务低于几十微秒时，派生与队列操作的固定开销开始反噬。Cilk 的经验法则是让串行叶子承担上千条指令，把调度开销摊到不足百分之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假设任务基本不共享可变状态；共享数据结构本身怎么办，是下一课 lock-free 的主题。优先级、实时与亲和约束不写——那是操作系统调度器的事；Cilk、TBB、OpenMP task 的语法差异点名即可。跨机器的任务分发也不在：那是 MPI 一侧的作业系统，记账单位从任务变成消息。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任务并行处理运行时才现身的并行度；fork-join 与工作窃取是标准表达。</li><li>粒度靠 cutoff：太粗不平衡，太细被调度开销反噬。</li><li>期望时间 \\(\\le W/P+O(S)\\)、空间 \\(O(P\\cdot S_1)\\)；任务多不等于快，跨度是硬下界。</li><li>流水线是按阶段切的任务并行，硬件与模型切分里各有一次兑现。</li><li>出处：Blumofe and Leiserson, JACM 1999；Frigo, Leiserson, Randall, PLDI 1998。</li></ul><p><span class="marginnote">为什么两端要分 LIFO/FIFO：自己从底端拿最新压入的任务，数据还在缓存里、递归下一层正好接着干（局部性）；小偷从顶端拿最老的任务，那是分出来的最大块——偷一次就转移一大片工作，不用来回偷。两端分开，自己人和小偷几乎不打架。</span></p>',6))])}const C=A(d,[["render",f]]);export{D as __pageData,C as default};
